    "imageUrl": "/images/e001_eco_sustentabilidade_v1.jpg",
    "imageCaption": "Diagrama esquemático de eco-sustentabilidade no ateliê: fiação de PET reciclado em cone de bordado, entretelas e descarte seguro.",
